  document.addEventListener('keydown', ev => { const el = ev.target; if (!el || !el.classList || !el.classList.contains('afi-slider-v2__number') || ev.isComposing) return; if (ev.key === 'Enter') { ev.preventDefault(); sldCommit(el); el.select(); } else if (ev.key === 'Escape') { ev.stopPropagation(); el.value = el._old != null ? el._old : el.value; el.blur(); } });
