      return dlgShell('drawer', 'md', d.id ? 'Editar medida personalizada' : 'Medida personalizada', '',
        '<div class="a-fields">' + field('dn', 'Nombre de la medida', d.name, '') + field('dc', 'Coste', d.cost ? eur(d.cost) : '', '€') + '</div>',
        (d.id ? btn('Eliminar', 'data-a="cdel"', { kind: 'sec' }) : '') + btn('Cancelar', 'data-a="close"', { kind: 'sec' }) + btn('Guardar', 'data-a="csave"'));
