    let s = '--afi-drawer-left:' + (st ? Math.max(0, Math.round(st.getBoundingClientRect().left)) : 0) + 'px;';
    if (pv) { const x = Math.round(pv.getBoundingClientRect().left); s += '--afi-drawer-scrim:linear-gradient(to right,var(--overlay-blanket) 0,var(--overlay-blanket) ' + x + 'px,transparent ' + x + 'px);'; }
    return s;
