  function updDrawer() {
    const d = S.drawer; if (!d || d.custom) return; const m = MEAS[d.id];
    const a = d.auto ? ma(d.id) : (m.f ? d.vals[0] * d.vals[1] : d.cost);
    const set = (id, v) => { const el = $('#' + id); if (el) el.textContent = v; };
    set('d-a', eur(a) + ' €'); set('d-f', d.id === 'cert' ? '—' : eur(fee(d.id, a)) + ' €'); set('d-c', m.cae ? '-' + eur(a * m.cae) + ' €' : '—');
  }
  /* v138: «Leer más aquí» (CAE) opens a right drawer with accordions like ¿Qué es? / ¿Cómo lo calculamos?; text supplied by Richard 2026-11-06 */
  const CAE_TXT = [
    ['¿Qué son los CAE?', '<p>Son documentos oficiales que acreditan de manera verificable el ahorro energético conseguido tras aplicar una medida de eficiencia (aislamiento, sustitución de equipos, etc.).</p><p>Un CAE tiene un valor único de 1 kWh de ahorro de consumo de energía final.</p>'],
    ['¿Qué utilidad tienen?', '<p>Los CAE permiten que el ahorro energético conseguido en tu vivienda o edificio quede oficialmente reconocido. Esto supone disponer de un respaldo que acredita tus mejoras, que puede servir para acceder a determinadas ayudas, justificar la eficiencia alcanzada y, en última instancia, reflejar un ahorro en el consumo energético de tu inmueble.</p>'],
    ['¿Quién puede obtenerlos?', '<p>Cualquier propietario, comunidad de vecinos o empresa que ejecute una medida reconocida como generadora de CAE. La asignación depende de la tipología de obra y del ahorro energético certificado.</p>'],
    ['¿Qué requisitos se exigen?', '<ul><li>La actuación debe estar recogida en un catálogo oficial de medidas estandarizadas o contar con una certificación específica de ahorro.</li><li>El ahorro debe ser validado mediante documentación técnica y certificados de eficiencia energética expedidos por profesionales competentes.</li></ul>'],
    ['¿Cómo se gestionan?', '<p>El propietario no tiene que tramitarlo directamente: suele hacerlo una empresa colaboradora o una entidad gestora de CAE, que se encarga de su validación y, en su caso, de su venta.</p>'],
    ['¿Qué beneficios aporta?', '<ul><li>Reconocimiento oficial del ahorro energético conseguido.</li><li>Posibilidad de obtener ingresos adicionales a través de la venta de los CAE.</li><li>Contribución a los objetivos nacionales de eficiencia energética.</li></ul>'],
    ['Normas comunes a los CAE', '<ul><li>Un mismo ahorro no puede contabilizarse dos veces (no es compatible con otros certificados por la misma medida).</li><li>Los CAE solo son válidos si están verificados por el sistema oficial y registrados en la plataforma nacional.</li><li>La vigencia de los certificados depende de la fecha de emisión y debe ajustarse al marco legal vigente.</li></ul>']
  ];
  const IRPF_TXT = [
    ['¿Qué viviendas pueden acogerse a la deducción?', '<p>Viviendas, plazas de garaje y trasteros que sean de tu propiedad y que se encuentren en edificios de uso predominante residencial.</p><p>Esta deducción no será aplicable a aquella parte de la vivienda que esté afecta a una actividad económica.</p>'],
    ['¿Cuál es el importe a deducir en tu declaración de IRPF?', '<ul><li>Cuando se haya emitido un certificado en el ejercicio, el 60 % de las cantidades satisfechas desde el 6 de octubre de 2021 hasta la fecha de finalización del ejercicio con un importe máximo de base de la deducción de 5.000 €.</li><li>Cuando se haya emitido el certificado en un ejercicio anterior, el 60 % de las cantidades satisfechas con un importe máximo de base de la deducción de 5.000 €.</li></ul><p>Las cantidades satisfechas que no se puedan deducir por exceder de la base máxima anual se podrán deducir, con el mismo límite (5.000 €), en los cuatro ejercicios siguientes, sin que en ningún caso la base acumulada de la deducción pueda exceder de 15.000 €.</p><p>Cuando las obras las realice una comunidad de propietarios, la base de esta deducción para cada propietario vendrá determinada por el resultado de aplicar a las cantidades satisfechas por la comunidad el coeficiente de participación que corresponda a cada uno de los propietarios.</p>'],
    ['¿Qué tipo de obras dan derecho a la deducción?', '<p>Aquellas que reduzcan el consumo de energía primaria no renovable, en un 30 % como mínimo, o bien, la mejora de la calificación energética del edificio para obtener una clase energética «A» o «B», en la misma escala de calificación.</p><p>Dicha reducción deberá ser acreditada mediante el correspondiente certificado de eficiencia energética emitido por un técnico competente antes del inicio de las obras (válido como máximo en los dos años anteriores a su inicio) y otro al finalizarlas.</p>'],
    ['¿Qué plazo hay para la realización de las obras?', '<p>Desde el 6 de octubre de 2021 hasta el 31 de diciembre de 2025.</p>'],
    ['¿En qué año puedes aplicar la deducción?', '<p>En 2021, 2022, 2023, 2024, 2025 y 2026, siendo necesario para la aplicación de dicha deducción el certificado de eficiencia energética emitido después de las obras.</p><p>En todo caso, el certificado deberá ser expedido antes del 1 de enero de 2026.</p>'],
    ['Normas comunes a las deducciones', '<ul><li>En País Vasco, las deducciones fiscales por obras de mejora de vivienda habitual no se aplican.</li><li>Las deducciones no son compatibles entre sí para la misma obra.</li><li>Las cantidades deben ser pagadas mediante tarjeta de crédito o débito, transferencia bancaria, cheque nominativo o ingreso en cuentas en entidades de crédito, a las personas o entidades que realicen tales obras, así como a las personas o entidades que expidan los citados certificados.</li><li>Las subvenciones recibidas a través de un programa de ayudas públicas, o que vayan a recibirse en virtud de resolución definitiva de la concesión de tales ayudas deberán descontarse.</li><li>No dan derecho a la deducción las cantidades satisfechas mediante entregas de dinero de curso legal.</li><li>Se consideran parte del coste de la obra los gastos necesarios para su ejecución, incluyendo los honorarios profesionales, costes de redacción de proyectos técnicos, dirección de obras, coste de ejecución de obras o instalaciones, inversión en equipos y materiales y otros gastos necesarios para su desarrollo, así como la emisión de los correspondientes certificados de eficiencia energética. No se consideran en dichas cantidades los costes relativos a la instalación o sustitución de equipos que utilicen combustibles de origen fósil.</li><li>Los certificados de eficiencia energética deben ser expedidos y registrados con arreglo a lo dispuesto en el Real Decreto 390/2021, de 1 de junio, por el que se aprueba el procedimiento básico para la certificación de la eficiencia energética de los edificios.</li><li>No se integrarán en la base imponible del IRPF las ayudas destinadas a compensar los costes derivados de la recepción o acceso a los servicios de comunicación audiovisual televisiva en las edificaciones afectadas por la liberación del dividendo digital y las concedidas en virtud de determinados programas en materia de rehabilitación energética.</li></ul>']
  ];
